import type { Metadata } from "next";
import type { MediaItem } from "@/lib/content/media";

/** Largest photo variant that social cards accept comfortably (they downscale anything bigger). */
const SHARE_IMAGE_MAX_WIDTH = 1600;
/** Site-wide share card, generated by src/app/og.png/route.tsx. */
const DEFAULT_SHARE_IMAGE = { url: "/og.png", width: 1200, height: 630, alt: "John Ojo, software engineer" };

/**
 * Per-page metadata: description, canonical URL and the matching Open Graph URL, so a shared link
 * points at the page itself rather than the homepage. `image` overrides the site-wide share card.
 */
export function pageMeta({ title, description, path, image }: { title?: string; description: string; path: string; image?: MediaItem | null }): Metadata {
  const photo = image?.type === "photo" ? [...image.variants].reverse().find((v) => v.w <= SHARE_IMAGE_MAX_WIDTH) ?? image.variants[0] : null;
  return {
    ...(title ? { title } : {}),
    description,
    alternates: { canonical: path },
    openGraph: {
      url: path,
      description,
      images: [photo && image ? { url: photo.jpg, width: photo.w, height: Math.round((photo.w * image.h) / image.w), alt: image.alt } : DEFAULT_SHARE_IMAGE],
    },
  };
}
